@prefix dc: <http://purl.org/dc/elements/1.1/> .
@prefix dcterms: <http://purl.org/dc/terms/> .
@prefix foaf: <http://xmlns.com/foaf/0.1/> .
@prefix ns: <http://www.w3.org/2003/06/sw-vocab-status/ns#> .
@prefix ns2: <https://w3id.org/cacao/ontology/> .
@prefix ns3: <http://www.cidoc-crm.org/cidoc-crm/> .
@prefix odrl: <http://www.w3.org/ns/odrl/2/> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix schema: <https://schema.org/> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/Telegram_Vikelas_Dimitrios> rdf:type ns3:E73_Information_Object, schema:TextObject ;
    ns3:P1_is_identified_by "Clipping of Vikelas Dimitrios' telegram" ;
    ns3:P3_has_note "announcing that the Paris Congress expresses the hope that the celebration of the first International Olympic Games will take place in Athens in 1896" ;
    ns3:P14_carried_out_by <http://example.org/Vikelas_Dimitrios> ;
    ns3:P7_took_place_at <http://example.org/Paris>, <http://example.org/Athens> ;
    schema:dateSent "1894-06-23"^^xsd:date .

<http://example.org/Vikelas_Dimitrios> rdf:type ns3:E21_Person ;
    ns3:P1_is_identified_by "Vikelas Dimitrios" ;
    foaf:interest <http://example.org/Panhellenic_Gymnastic_Association> .

<http://example.org/Panhellenic_Gymnastic_Association> rdf:type foaf:Organization ;
    ns3:P1_is_identified_by "Panhellenic Gymnastic Association" .

<http://example.org/Paris> rdf:type ns3:E53_Place, schema:Place ;
    ns3:P1_is_identified_by "Paris" .

<http://example.org/Athens> rdf:type ns3:E53_Place, schema:Place ;
    ns3:P1_is_identified_by "Athens" .

<http://example.org/International_Olympic_Games_1896> rdf:type ns3:E5_Event ;
    ns3:P1_is_identified_by "first International Olympic Games" ;
    ns3:P7_took_place_at <http://example.org/Athens> ;
    schema:startDate "1896"^^xsd:gYear .
